// Command crowctl drives the Crow Terraform-module registry from CI.
//
// Subcommands:
//   - validate:      check that each module in the changeset has a coherent
//     VERSION bump and that its version is not already
//     published in Crow. Used on PRs.
//   - upload:        tar each module in the changeset and PUT it to Crow.
//     Used on pushes to master.
//   - list-versions: list the published versions for a single module.
//     Intended for manual / debugging use.
//
// Environment:
//
//	CROW_URL  overrides the default https://crow.infrastructure.immuta.io.
//
// Logs go to stderr; the --json flag emits them as structured slog JSON.
package main

import (
	"context"
	"errors"
	"log/slog"
	"os"
	"time"

	"github.com/immuta/operations/apps/crowctl/cmd"
	"github.com/immuta/operations/libs/clog"
	"github.com/urfave/cli/v3"
)

func main() {
	app := &cli.Command{
		Name:  "crowctl",
		Usage: "Validate, upload, and inspect Terraform modules in Crow",
		Flags: []cli.Flag{
			&cli.StringFlag{
				Name:    "crow-url",
				Usage:   "Crow base URL",
				Value:   "https://crow.infrastructure.immuta.io",
				Sources: cli.EnvVars("CROW_URL"),
			},
			&cli.BoolFlag{
				Name:  "json",
				Usage: "emit structured JSON logs",
			},
			&cli.DurationFlag{
				Name:  "timeout",
				Usage: "per-operation HTTP timeout",
				Value: 30 * time.Second,
			},
		},
		Before: func(ctx context.Context, cmd *cli.Command) (context.Context, error) {
			if cmd.Bool("json") {
				slog.SetDefault(slog.New(slog.NewJSONHandler(os.Stderr, nil)))
				return ctx, nil
			}
			ctx = clog.AddLoggerToContext(ctx, os.Stderr, clog.LogOpts{
				Level: slog.LevelInfo,
			})
			slog.SetDefault(clog.GetLoggerFromContext(ctx))
			return ctx, nil
		},
		Commands: []*cli.Command{
			{
				Name:      "validate",
				Usage:     "Check that changed modules' versions are not already published in Crow",
				ArgsUsage: "<changed-file> [changed-file...]",
				Action: func(ctx context.Context, c *cli.Command) error {
					return cmd.Validate(ctx, cmd.ValidateOptions{
						CrowURL:      c.String("crow-url"),
						Timeout:      c.Duration("timeout"),
						ChangedFiles: c.Args().Slice(),
					})
				},
			},
			{
				Name:      "upload",
				Usage:     "Tar each changed module and PUT it to Crow",
				ArgsUsage: "<changed-file> [changed-file...]",
				Action: func(ctx context.Context, c *cli.Command) error {
					return cmd.Upload(ctx, cmd.UploadOptions{
						CrowURL:      c.String("crow-url"),
						Timeout:      c.Duration("timeout"),
						ChangedFiles: c.Args().Slice(),
					})
				},
			},
			{
				Name:      "list-versions",
				Usage:     "List published versions for a module",
				ArgsUsage: "<namespace> <name> <provider>",
				Action: func(ctx context.Context, c *cli.Command) error {
					args := c.Args().Slice()
					if len(args) != 3 {
						return errors.New("list-versions requires 3 args: <namespace> <name> <provider>")
					}
					return cmd.ListVersions(ctx, cmd.ListVersionsOptions{
						CrowURL:   c.String("crow-url"),
						Timeout:   c.Duration("timeout"),
						Namespace: args[0],
						Name:      args[1],
						Provider:  args[2],
					})
				},
			},
		},
	}

	if err := app.Run(context.Background(), os.Args); err != nil {
		slog.Error("crowctl failed", "error", err)
		os.Exit(1)
	}
}

